<script setup lang="ts">
import{computed,onUnmounted,ref,watch}from'vue';
import{rulerTicks}from'../../../packages/comp-bridge/view-settings.mjs';
import{parityMessages}from'./parity-labels';
import type{Language}from'./types';
const props=defineProps<{language:Language;width:number;height:number;zoom:number;resolution:number;unit:string;viewport:{x:number;y:number;w:number;h:number};disabled:boolean;owner:{id:string;revision:string}}>(),emit=defineEmits(['guide','gesture']),root=ref<HTMLDivElement>(),draft=ref<{axis:string;position:number}>(),t=computed(()=>parityMessages[props.language]);
const horizontal=computed(()=>rulerTicks(props.width,props.zoom,props.viewport.x,props.viewport.w)),vertical=computed(()=>rulerTicks(props.height,props.zoom,props.viewport.y,props.viewport.h));
const label=(position:number)=>{const number=props.unit==='in'?position/props.resolution:props.unit==='cm'?position/props.resolution*2.54:position;return Number(number.toFixed(props.unit==='px'?2:2));};
let owner:any,dragging=false;
function move(event:PointerEvent){if(!dragging||!draft.value)return;const bounds=root.value!.getBoundingClientRect(),position=(draft.value.axis==='horizontal'?event.clientY-bounds.top:event.clientX-bounds.left)/props.zoom;draft.value.position=position;}
function start(event:PointerEvent,axis:string){if(props.disabled||event.button!==0)return;owner={...props.owner};draft.value={axis,position:0};dragging=true;(event.currentTarget as SVGSVGElement).setPointerCapture(event.pointerId);(event.currentTarget as SVGSVGElement).focus();emit('gesture',true);move(event);}
function end(event:PointerEvent){if(!dragging||!draft.value)return;move(event);const guide={...draft.value},valid=guide.position>=0&&guide.position<=(guide.axis==='horizontal'?props.height:props.width);cancel();if(valid)emit('guide',{...guide,owner});}
function cancel(){dragging=false;draft.value=undefined;emit('gesture',false);}
watch(()=>props.owner.id+':'+props.owner.revision,cancel);onUnmounted(cancel);
</script>
<template><div ref="root" class="rulers" @pointerdown.stop @pointermove.stop @pointerup.stop @pointercancel.stop @keydown.esc.stop.prevent="cancel"><svg data-testid="horizontal-ruler" class="horizontal-ruler" tabindex="0" role="img" :aria-label="t.horizontalRuler" :viewBox="`0 0 ${width*zoom} 22`" preserveAspectRatio="none" @pointerdown="start($event,'horizontal')" @pointermove="move" @pointerup="end" @pointercancel="cancel"><g v-for="tick in horizontal" :key="tick.position"><line :x1="tick.position*zoom" :x2="tick.position*zoom" :y1="tick.major?12:17" y2="22"/><text v-if="tick.major" :x="tick.position*zoom+3" y="10">{{label(tick.position)}}</text></g></svg><svg data-testid="vertical-ruler" class="vertical-ruler" tabindex="0" role="img" :aria-label="t.verticalRuler" :viewBox="`0 0 22 ${height*zoom}`" preserveAspectRatio="none" @pointerdown="start($event,'vertical')" @pointermove="move" @pointerup="end" @pointercancel="cancel"><g v-for="tick in vertical" :key="tick.position"><line :y1="tick.position*zoom" :y2="tick.position*zoom" :x1="tick.major?12:17" x2="22"/><text v-if="tick.major" :transform="`translate(10 ${tick.position*zoom+3}) rotate(-90)`">{{label(tick.position)}}</text></g></svg><svg v-if="draft" class="ruler-guide" :viewBox="`0 0 ${width} ${height}`"><line :x1="draft.axis==='vertical'?draft.position:0" :x2="draft.axis==='vertical'?draft.position:width" :y1="draft.axis==='horizontal'?draft.position:0" :y2="draft.axis==='horizontal'?draft.position:height" stroke="#71dfed" :stroke-width="1/zoom"/></svg></div></template>
<style scoped>.rulers{position:absolute;inset:0;pointer-events:none}.rulers svg.horizontal-ruler{position:absolute;left:0;top:-24px;width:100%;height:22px}.rulers svg.vertical-ruler{position:absolute;top:0;left:-24px;height:100%;width:22px}.horizontal-ruler,.vertical-ruler{pointer-events:auto;touch-action:none;background: var(--surface);color: var(--text);overflow:hidden;cursor:crosshair}.rulers line{stroke:currentColor;stroke-width:1}.rulers text{font:9px sans-serif;fill:currentColor}.ruler-guide{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}</style>
